let all_news = "";
let matchCount = 0;

// 1. 定義嚴格的防災/氣象白名單關鍵字
const whiteList = ["颱風", "暴風", "大雨", "豪雨", "淹水", "積水", "災情", "路樹", "倒塌", "停班", "停課"];

// 2. 定義黑名單（物理阻斷容易引發模型亂講歷史舊聞的字眼）
const blackList = ["地震", "新冠", "確診", "武漢肺炎", "英特爾", "加州"];

for (const item of $input.all()) {
  const title = item.json.title || "";
  const snippet = item.json.contentSnippet || "";
  const fullText = (title + snippet).toLowerCase();

  // 檢查是否命中白名單，且不包含黑名單
  const hasWhiteKeyword = whiteList.some(key => fullText.includes(key));
  const hasBlackKeyword = blackList.some(key => fullText.includes(key));

  if (hasWhiteKeyword && !hasBlackKeyword) {
    matchCount++;
    all_news += `【氣象新聞 ${matchCount}】\n標題：${title}\n摘要：${snippet}\n---\n`;
  }
}

// 3. 關鍵防禦：如果過濾後完全沒有相關新聞，直接給出死板的無資料宣告，絕不留給 LLM 任何瞎編空間
if (all_news === "") {
  all_news = "情報回報：今日台灣地區無任何颱風、路樹倒塌或停班停課之相關公開民生防災消息。";
}

return [{ json: { all_news_text: all_news } }];

// 1. 抓取 Merge 節點進來的兩個輸入源
const items = $input.all();

// 2. 提取財經大腦內容、防災內容
const financeReport = items[0]?.json?.content || ""; 
const weatherReport = items[1]?.json?.content || ""; 

// 從 Code in JavaScript1 的上游節點中撈取分類好的超連結新聞清單
const newsList = $node["Code in JavaScript1"].json.news_list_html || "";

// 3. 組裝第一則訊息：AI 綜觀摘要 + 颱風動態
let messageAi = `🔔 <b>FED 利率與基欽週期 AI 綜觀摘要</b>：\n\n${financeReport}\n\n`;
if (weatherReport && weatherReport.trim() !== "") {
  messageAi += `⚠️ <b>颱風動態與民生防災重點</b>：\n${weatherReport}\n\n`;
}

// 4. 組裝第二則訊息：今日財經新聞來源清單（含超連結）
let messageLinks = `📰 <b>今日財經新聞來源清單</b>：\n${newsList}\n`;

// 5. 獨立安全截斷防禦（按行切分，確保各自不爆 4096 字元且 HTML 標籤完整）
function safeTruncate(rawText, maxLen = 3900) {
  const lines = rawText.split("\n");
  let finalReport = "";
  let isTruncated = false;
  for (const line of lines) {
    if ((finalReport + line + "\n").length > maxLen) {
      isTruncated = true;
      break;
    }
    finalReport += line + "\n";
  }
  if (isTruncated) {
    finalReport += "\n...(因字數超限，後續內容已省略)...";
  }
  return finalReport.trim();
}

return [{ 
  json: { 
    message_ai: safeTruncate(messageAi),
    message_links: safeTruncate(messageLinks)
  } 
}];

