let all_news = "";
const savedTitles = []; // 用陣列存放已保留的清單，進行模糊比對
const newsByCategory = {}; // 用來按來源分類新聞的物件
let count = 0;

// HTML 安全轉義函式，防止 Telegram 報錯
function escapeHtml(text) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// 1. 遍歷並過濾所有輸入的 RSS 財經新聞
for (const item of $input.all()) {
  const title = (item.json.title || "無標題").trim();
  let snippet = (item.json.contentSnippet || "").trim();
  const link = (item.json.link || "#").trim();

  // 嘗試解析新聞來源
  let source = "財經綜合報導";
  if (title.includes(" - ")) {
    const parts = title.split(" - ");
    source = parts[parts.length - 1].trim();
  }

  // 【強化版模糊去重防禦】
  const cleanTitle = title.replace(/[\s\-_|、，。：:【】「」｜(（)）]/g, ""); 

  let isDuplicate = false;
  for (const existingTitle of savedTitles) {
    if (cleanTitle.includes(existingTitle) || existingTitle.includes(cleanTitle)) {
      isDuplicate = true;
      break;
    }
    if (cleanTitle.substring(0, 7) === existingTitle.substring(0, 7)) {
      isDuplicate = true;
      break;
    }
  }

  if (isDuplicate) {
    continue; // 命中重複，跳過
  }

  // 【純財經、總經與國家政策關鍵字篩選】
  const financeKeywords = [
    "股", "台積電", "營收", "大盤", "指", "ETF", "外資", "證券", "經濟", "財經", "上市",
    "美聯儲", "聯準會", "Fed", "升息", "降息", "利率", "國際政經", "政經", "基欽週期", "週期",
    "前瞻", "國發會", "國發基金", "產業政策", "國家發展", "預算", "特別預算", "補助", "政策利多", "本土化",
    "AI新十大建設", "信賴產業", "軍工", "無人機", "綠能", "主權AI"
  ];
  const isFinance = financeKeywords.some(word => title.includes(word) || snippet.includes(word));

  if (!isFinance) {
    continue; 
  }

  // ─── 通過過濾，確定保留新聞 ───
  if (cleanTitle.length > 0) {
    savedTitles.push(cleanTitle); 
  }

  count++;

  // 1. 餵給 AI 分析用的純文字
  all_news += `新聞 [${count}] (來源：${source})\n標題：${title}\n摘要：${snippet}\n---\n`;

  // 2. 依來源分類收集 HTML 資料
  const safeTitle = escapeHtml(title);
  const safeLink = link.replace(/&/g, "&amp;");
  const htmlItem = `  • <a href="${safeLink}">${safeTitle}</a>\n`;

  if (!newsByCategory[source]) {
    newsByCategory[source] = [];
  }
  newsByCategory[source].push(htmlItem);
}

// 3. 將分類好的物件組合為條列式 HTML 文本
let news_list_html = "";
if (count > 0) {
  for (const source in newsByCategory) {
    const safeSource = escapeHtml(source);
    news_list_html += `<b>【${safeSource}】</b>\n`; // 媒體來源做成粗體大分類
    news_list_html += newsByCategory[source].join(""); // 塞入該媒體的所有新聞
    news_list_html += `\n`; // 分類間空一行
  }
}

// 修正時區問題
const today = new Date();
const formattedDate = today.toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei' });
let usGovContext = "現任美國總統：唐納·川普（Donald Trump，第 47 任）[2026年執政]。政策：美國優先、關稅保護。";

if (all_news.trim() === "") {
  all_news = "今日無相關公開財經焦點情報。";
  news_list_html = "今日無相關公開財經焦點情報。\n";
}

return [{ 
  json: { 
    current_date: formattedDate,
    us_gov_context: usGovContext,
    all_news_text: all_news,
    news_list_html: news_list_html.trim() 
  } 
}];
